WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_rd_cy_decimal'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '循环小数与周期', 'kp-rd-cy-decimal', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "循环与余数周期"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "找准循环节，用总数除以循环节长度，看余数定位置。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“红黄蓝绿紫五种颜色的彩灯依次闪烁。第 2023 次闪烁的是什么颜色？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[确定循环节的长度(如5种颜色, 长度=5)] --> B[用目标序号 2023 ÷ 5]\nB --> C[看余数: 2023 ÷ 5 = 404 余 3]\nC --> D{余数是几?}\nD -- 余1 --> E[第一种颜色: 红]\nD -- 余3 --> F[第三种颜色: 蓝]\nD -- 没余数(整除) --> G[循环节的最后一个颜色: 紫]"}}]}$$ AS jsonb), NULL, '循环小数与周期的核心考点与实战推导。', category_node.id, CAST('["数量关系", "循环小数与周期"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_rd_cy_decimal", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
